const event = $input.first().json;
return [{ json: {
  workflow_name: event.workflow?.name ?? 'unknown',
  workflow_id: event.workflow?.id ?? null,
  execution_id: event.execution?.id ?? null,
  execution_url: event.execution?.url ?? null,
  last_node_executed: event.execution?.lastNodeExecuted ?? null,
  error_message: event.execution?.error?.message ?? 'No error message supplied',
  observed_at: new Date().toISOString(),
  action_required: 'Connect this output to your chosen notification or incident log. Do not include secrets or customer data in alerts.'
}}];
